const number=value=>new Intl.NumberFormat('ko-KR',{maximumFractionDigits:2}).format(value);
export function attributeFacts(field){
  const choices=field.type==='reaction'?Object.entries(REACTIONS).map(([key,item])=>({key,label:item.label})):field.options;
  const range=choices?`선택 ${choices.length}가지`:`${number(field.min)}~${number(field.max)}${field.unit?' '+field.unit:''}`;
  const fallback=choices?.find(item=>item.key===field.default)?.label ?? (field.default===undefined?null:`${number(field.default)}${field.unit?' '+field.unit:''}`);
  return range+(fallback===null?'':` · 누락 시 ${fallback}`);
}
export function participantHelp(key){
  const field=PARTICIPANT_ATTRIBUTES.find(item=>item.key===key),help=PARTICIPANT_HELP[key];
  if(!field || !help)throw new Error(`참여자 속성 설명 누락: ${key}`);
  return {key,label:field.label,facts:attributeFacts(field),...help};
}

